#!/usr/bin/env node
// Copies the compiled MediatedEscrow ABI into the mediator and web packages as typed TS constants.
// Run after `forge build` (contracts/): node scripts/export-abi.mjs
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const artifact = JSON.parse(
  readFileSync(join(root, "contracts/out/MediatedEscrow.sol/MediatedEscrow.json"), "utf8"),
);
const body =
  "// Generated by scripts/export-abi.mjs from contracts/out. Do not edit by hand.\n" +
  `export const mediatedEscrowAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;

for (const target of ["mediator/src/abi.ts", "web/lib/abi.ts"]) {
  const file = join(root, target);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, body);
  console.log("wrote", target);
}
